# Generated by omh docs agent-skills; edit the catalog/producer, not this file.
param([switch]$User)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if ($args.Count) { throw 'Usage: install.ps1 [-User]' }
$base = (Get-Location).ProviderPath
if ($User) {
    $base = $env:USERPROFILE
    if (-not $base) { $base = $env:HOME }
    if (-not $base) { throw 'User profile is required for -User' }
    $target = Join-Path $base '.agents/skills'
} else {
    $target = Join-Path $base '.agents/skills'
}
$source = Join-Path (Split-Path -Parent $PSScriptRoot) 'agent-skills'
$inventory = Join-Path $source '.omh-agent-skills-manifest.json'
if (-not (Test-Path -LiteralPath $inventory -PathType Leaf)) { throw 'Missing source inventory' }
$inventoryPath = (Get-Item -Force -LiteralPath $inventory).FullName
# The receipt is the one inventory: generated beside the pack, pinned by the
# docs gate, and copied verbatim after every listed file verifies.
$entries = @((Get-Content -Raw -Encoding UTF8 -LiteralPath $inventory | ConvertFrom-Json).files.PSObject.Properties |
    ForEach-Object { [PSCustomObject]@{ Path = $_.Name; Hash = [string]$_.Value } })
if (-not $entries.Count) { throw 'Empty source inventory' }
function Assert-NoLink([string]$Path, [string]$Boundary) {
    $current = $Path
    while ($current -and $current -ne $Boundary) {
        if (Test-Path -LiteralPath $current) {
            $item = Get-Item -Force -LiteralPath $current
            if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
                throw "Reparse-point path: $current"
            }
        }
        $current = Split-Path -Parent $current
    }
}
Assert-NoLink $source (Split-Path -Parent $source)
$items = @(Get-ChildItem -Force -Recurse -LiteralPath $source)
foreach ($item in $items) {
    if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
        throw "Reparse-point source: $($item.FullName)"
    }
}
$sourceFiles = @($items | Where-Object { -not $_.PSIsContainer -and $_.FullName -ne $inventoryPath })
if ($sourceFiles.Count -ne $entries.Count) { throw 'Source file inventory mismatch' }
function Assert-Digests([string]$Root) {
    foreach ($entry in $entries) {
        $path = Join-Path $Root $entry.Path
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing skill: $path" }
        if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $entry.Hash) {
            throw "Skill digest mismatch: $path"
        }
    }
}
Assert-Digests $source
# Preflight the receipt as well as every copied file before any write.
foreach ($relative in (@($entries.Path) + '.omh-agent-skills-manifest.json')) {
    $path = Join-Path $target $relative
    Assert-NoLink $path $base
    if ((Test-Path -LiteralPath $path) -and -not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Not a file: $path"
    }
}
foreach ($entry in $entries) {
    $path = Join-Path $target $entry.Path
    [IO.Directory]::CreateDirectory((Split-Path -Parent $path)) | Out-Null
    [IO.File]::Copy((Join-Path $source $entry.Path), $path, $true)
}
Assert-Digests $target
[IO.File]::Copy($inventory, (Join-Path $target '.omh-agent-skills-manifest.json'), $true)
Write-Output "Installed openclaw skills in $target"
$skills = [Collections.Generic.SortedSet[string]]::new([StringComparer]::Ordinal)
foreach ($entry in $entries) { [void]$skills.Add($entry.Path.Split('/')[0]) }
$skills
